"""Deterministic schema source. No credentials or sample production records."""
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
M=ROOT/'supabase/migrations'
SCHEMA={}
parts=[]
def emit(s):parts.append(s.strip()+'\n')
def table(name,cols,refs=(),checks=(),uniques=(),tenant=True,mutable=True):
    fields=['id uuid PRIMARY KEY DEFAULT gen_random_uuid()']
    if tenant:fields+=['tenant_id uuid NOT NULL REFERENCES inventory.tenants(id) ON DELETE RESTRICT']
    fields+=cols
    fields+=['created_at timestamptz NOT NULL DEFAULT clock_timestamp()']
    if mutable:fields+=['updated_at timestamptz NOT NULL DEFAULT clock_timestamp()', 'row_version bigint NOT NULL DEFAULT 1 CHECK(row_version>0)']
    if tenant:fields+=['UNIQUE(tenant_id,id)']
    for field,target in refs:
        fields += [f'FOREIGN KEY(tenant_id,{field}) REFERENCES inventory.{target}(tenant_id,id) ON DELETE RESTRICT']
    fields += ['CHECK('+c+')' for c in checks]
    fields += ['UNIQUE('+','.join(c)+')' for c in uniques]
    emit('CREATE TABLE inventory.'+name+' (\n  '+',\n  '.join(fields)+'\n);')
    SCHEMA[name]={'tenant':tenant,'mutable':mutable,'columns':fields,'refs':list(refs)}
    if tenant:
        emit(f'CREATE INDEX ON inventory.{name}(tenant_id,created_at,id);')
        for field,target in refs:emit(f'CREATE INDEX ON inventory.{name}(tenant_id,{field});')

def ref(field,target,nullable=True):return (f'{field} uuid'+('' if nullable else ' NOT NULL'),(field,target))
def master(name,extra=(),refs=()):
    table(name,['code text NOT NULL CHECK(length(code) BETWEEN 1 AND 64)','name text NOT NULL CHECK(length(name) BETWEEN 1 AND 300)',"status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','archived'))",*extra],refs=refs,uniques=[('tenant_id','code')])

def header(name,extra=(),refs=(),statuses="'draft','submitted','pending','partially_approved','approved','rejected','revision_required','cancelled','posted'"):
    table(name,['document_number text NOT NULL',f"status text NOT NULL DEFAULT 'draft' CHECK(status IN ({statuses}))",'business_date date NOT NULL DEFAULT CURRENT_DATE','requested_by uuid NOT NULL','revision integer NOT NULL DEFAULT 1 CHECK(revision>0)',*extra],refs=[('requested_by','tenant_memberships'),*refs],uniques=[('tenant_id','document_number')])
def line(name,parentfield,parent,extra=(),refs=()):
    table(name,[f'{parentfield} uuid NOT NULL','line_number integer NOT NULL CHECK(line_number>0)',*extra],refs=[(parentfield,parent),*refs],uniques=[('tenant_id',parentfield,'line_number')])

emit('''-- Generated by scripts/generate_schema.py. Apply once in migration order.
CREATE SCHEMA inventory;
CREATE SCHEMA inventory_security;
REVOKE ALL ON SCHEMA inventory,inventory_security FROM PUBLIC;
DO $$ BEGIN
 IF NOT EXISTS(SELECT FROM pg_roles WHERE rolname='inventory_runtime') THEN
 CREATE ROLE inventory_runtime NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS; END IF;
 IF NOT EXISTS(SELECT FROM pg_roles WHERE rolname='inventory_auth') THEN
 CREATE ROLE inventory_auth NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS; END IF;
END $$;
-- Existing roles must have safe attributes; never silently trust pre-existing privileges.
DO $$ BEGIN
 IF EXISTS(SELECT FROM pg_roles WHERE rolname IN ('inventory_runtime','inventory_auth')
 AND (rolsuper OR rolbypassrls OR rolcreaterole OR rolcreatedb OR rolreplication)) THEN
 RAISE EXCEPTION 'Unsafe pre-existing application role'; END IF;
 IF EXISTS(SELECT FROM pg_auth_members am JOIN pg_roles r ON r.oid=am.member WHERE r.rolname IN ('inventory_runtime','inventory_auth')) THEN
 RAISE EXCEPTION 'Application group roles must not inherit other roles'; END IF;
END $$;
GRANT USAGE ON SCHEMA inventory,inventory_security TO inventory_runtime,inventory_auth;
ALTER DEFAULT PRIVILEGES IN SCHEMA inventory REVOKE ALL ON TABLES FROM PUBLIC;
ALTER DEFAULT PRIVILEGES IN SCHEMA inventory_security REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC;
CREATE FUNCTION inventory_security.tenant_id() RETURNS uuid LANGUAGE sql STABLE
 SET search_path=pg_catalog AS $$SELECT nullif(current_setting('app.tenant_id',true),'')::uuid$$;
CREATE FUNCTION inventory_security.user_id() RETURNS uuid LANGUAGE sql STABLE
 SET search_path=pg_catalog AS $$SELECT nullif(current_setting('app.user_id',true),'')::uuid$$;
REVOKE ALL ON FUNCTION inventory_security.tenant_id(),inventory_security.user_id() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION inventory_security.tenant_id(),inventory_security.user_id() TO inventory_runtime,inventory_auth;
''')
