emit('CREATE UNIQUE INDEX ON inventory.inventory_stock_ledger(tenant_id,reversal_of) WHERE reversal_of IS NOT NULL;')
table('tenant_drive_connections',["auth_mode text NOT NULL CHECK(auth_mode IN ('oauth','service_account'))",'connection_version integer NOT NULL CHECK(connection_version>0)','root_folder_id text NOT NULL','drive_id text','google_identity text NOT NULL','token_ciphertext text','encryption_key_id text',"status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','ready','revoked','failed','retired'))",'last_tested_at timestamptz','capabilities jsonb NOT NULL DEFAULT \'{}\'::jsonb'],checks=["auth_mode<>'oauth' OR (token_ciphertext IS NOT NULL AND encryption_key_id IS NOT NULL)"],uniques=[('tenant_id','connection_version')])
emit("CREATE UNIQUE INDEX ON inventory.tenant_drive_connections(root_folder_id) WHERE status='ready';\nCREATE UNIQUE INDEX ON inventory.tenant_drive_connections(tenant_id) WHERE status='ready';")
table('tenant_drive_folders',['connection_id uuid NOT NULL','purpose text NOT NULL','google_folder_id text NOT NULL','parent_folder_id text NOT NULL'],refs=[('connection_id','tenant_drive_connections')],uniques=[('tenant_id','connection_id','purpose'),('tenant_id','connection_id','google_folder_id')])
table('file_attachments',['connection_id uuid NOT NULL','folder_id uuid NOT NULL','google_file_id text','original_filename text NOT NULL CHECK(length(original_filename) BETWEEN 1 AND 500)','mime_type text NOT NULL','file_size bigint NOT NULL CHECK(file_size>=0)','checksum text',"status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','uploading','verifying','ready','failed','quarantined','missing','archived'))", "sensitivity text NOT NULL DEFAULT 'normal' CHECK(sensitivity IN ('normal','sensitive'))",'uploaded_by uuid NOT NULL'],refs=[('connection_id','tenant_drive_connections'),('folder_id','tenant_drive_folders'),('uploaded_by','tenant_memberships')],checks=["status<>'ready' OR google_file_id IS NOT NULL"],uniques=[('tenant_id','google_file_id')])
emit('ALTER TABLE inventory.tenant_drive_folders ADD UNIQUE(tenant_id,id,connection_id);\nALTER TABLE inventory.file_attachments ADD FOREIGN KEY(tenant_id,folder_id,connection_id) REFERENCES inventory.tenant_drive_folders(tenant_id,id,connection_id);')
table('asset_attachments',['asset_id uuid NOT NULL','file_id uuid NOT NULL'],refs=[('asset_id','assets'),('file_id','file_attachments')],uniques=[('tenant_id','asset_id','file_id')])
table('document_attachments',['document_id uuid NOT NULL','file_id uuid NOT NULL'],refs=[('document_id','business_documents'),('file_id','file_attachments')],uniques=[('tenant_id','document_id','file_id')])
table('file_upload_operations',['file_id uuid NOT NULL','actor_id uuid NOT NULL','idempotency_key text NOT NULL','resumable_uri_ciphertext text','encryption_key_id text','expected_size bigint NOT NULL CHECK(expected_size>0)','confirmed_offset bigint NOT NULL DEFAULT 0 CHECK(confirmed_offset>=0)','lease_token_digest text','lease_expires_at timestamptz','expires_at timestamptz NOT NULL',"status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','uploading','verifying','ready','failed','expired'))"],refs=[('file_id','file_attachments'),('actor_id','tenant_memberships')],checks=['confirmed_offset<=expected_size',"status<>'ready' OR confirmed_offset=expected_size"],uniques=[('tenant_id','idempotency_key'),('tenant_id','file_id')])
table('file_access_logs',['file_id uuid NOT NULL','actor_id uuid NOT NULL',"action text NOT NULL CHECK(action IN ('preview','download','archive'))",'correlation_id text NOT NULL'],refs=[('file_id','file_attachments'),('actor_id','tenant_memberships')],mutable=False)
master('report_templates',['report_type text NOT NULL','version integer NOT NULL CHECK(version>0)','configuration jsonb NOT NULL'])
table('generated_reports',['template_id uuid NOT NULL','requested_by uuid NOT NULL','filters_snapshot jsonb NOT NULL','template_snapshot jsonb NOT NULL','file_id uuid',"format text NOT NULL CHECK(format IN ('pdf','xlsx'))", "status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','running','ready','failed'))"],refs=[('template_id','report_templates'),('requested_by','tenant_memberships'),('file_id','file_attachments')],checks=["status<>'ready' OR file_id IS NOT NULL"])
table('tenant_audit_logs',['actor_id uuid','actor_kind text NOT NULL CHECK(actor_kind IN (\'user\',\'system\',\'platform\'))','action text NOT NULL','resource_type text NOT NULL','resource_id uuid','correlation_id text NOT NULL','details jsonb NOT NULL DEFAULT \'{}\'::jsonb'],refs=[('actor_id','tenant_memberships')],mutable=False)
table('outbox_jobs',['job_type text NOT NULL','payload jsonb NOT NULL','idempotency_key text NOT NULL',"status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','running','done','failed','dead'))",'attempts integer NOT NULL DEFAULT 0 CHECK(attempts>=0)','max_attempts integer NOT NULL DEFAULT 5 CHECK(max_attempts>0)','available_at timestamptz NOT NULL DEFAULT clock_timestamp()','lease_token_digest text','lease_expires_at timestamptz','last_error_code text'],uniques=[('tenant_id','idempotency_key')])
emit("CREATE INDEX ON inventory.outbox_jobs(tenant_id,available_at) WHERE status IN ('pending','failed');")
table('idempotency_records',['operation text NOT NULL','idempotency_key text NOT NULL','request_digest text NOT NULL CHECK(request_digest ~ \'^[0-9a-f]{64}$\')','resource_id uuid','expires_at timestamptz NOT NULL'],uniques=[('tenant_id','operation','idempotency_key')])
